-- Garrick's Recap, generated by scripts/gen-garrick-recap-sql.ts from src/data/garrickRecap.ts. Do not edit by hand.
insert into public.garrick_recaps (series_id, season_number, data) values
('dark-moon', 1, '[{"week":1,"entries":[{"when":"","line":"*\"Garrick.\"*","meaning":"True: it is his name. He gives his own and asks for none of theirs. He has no need to: they are on the list he has been waiting for."},{"when":"","line":"*\"Woman called Meira. Scholar. Sat right there most nights, two years near enough. Cheapest wine in the house, and tipped like a queen. Left this. Hasn''t been back in three weeks.\"*","meaning":"True. He never claims she trusted him, and never explains why he kept them."},{"when":"","line":"*\"You {N} were on her list. That means something.\"*","meaning":"True. It means she identified the only people who could find the Stones — which is why he needs them."},{"when":"","line":"*\"She''d sit right there. I doubt she thought I was listening.\"*","meaning":"True. He was listening for two years — which is exactly how he knew when she had found enough to be worth killing."},{"when":"","line":"*\"I''ve a business to run.\"*","meaning":"True. Reluctance is the strongest possible cover for a man who needs to be invited rather than volunteer."},{"when":"","line":"*\"...As far as the Widow''s Tooth. That''s all I''m agreeing to.\"*","meaning":"True in that moment — it''s all he has agreed to. It leaves the door open for them to ask him again, which they do."},{"when":"If asked who attacked them","line":"*\"I know what she wrote down.\"*","meaning":"He never says it wasn''t his doing."},{"when":"If asked whether Meira sent the pages","line":"*\"She wrote them at that table, and took them with her when she left.\"*","meaning":"True."},{"when":"If asked where she went","line":"*\"She took her coat and those pages, and she didn''t come back.\"*","meaning":"True — every word."}]},{"week":2,"entries":[{"when":"Day 1, asked \"What do you know that you''re not telling us?\"","line":"*\"I can tell you where the next name on that wall lives. That''s where I''d start.\"*","meaning":"True — a narrower answer."},{"when":"","line":"*\"You saved that boy. Whatever else happened here, you saved him.\"*","meaning":"True, and genuinely meant. The children were never in danger of dying — they''re needed alive until the blooding. His warmth here is real, which is what makes it work."},{"when":"Gathering, over the ledger","line":"*\"This hand''s been keeping books like this for years. This isn''t new, and it isn''t finished. Two places. Two children.\"*","meaning":"True — he names the operation''s scale before the party has to. The hand isn''t his; the Order keeps its own clerks."},{"when":"If asked at the Gathering: \"Do you know the king''s name?\"","line":"*\"Malakor.\"* If asked how: *\"My grandmother taught me that name.\"*","meaning":"True. He gives the name the first time anyone asks."},{"when":"If asked why the Order takes children and not them","line":"*\"Look at the ledger. Every name in it is a child''s.\"*","meaning":"True — he points at the evidence, never at the real reason (they need the party free to find the Stones)."},{"when":"Only if someone asks him for the ledger","line":"*\"Here. Read every page.\"*","meaning":"True — an invitation, not a claim. Nothing in the book points at him."}]},{"week":3,"entries":[{"when":"Day 1, over Meira''s notes","line":"*\"Ashcombe''s a shepherds'' village on the edge of the burned country. A long day west. And above it she''s marked a place. The Blackglass.\"*","meaning":"True — he reads her shorthand, and says only what it says."},{"when":"Day 1, if the party raises the fourth name on the ledger and asks whether to go there first","line":"*\"One road at a time. The girl''s is the one with tracks on it.\"*","meaning":"True — Wren''s is the only trail with tracks. The steer: it keeps the party on one road while the fourth child is already held (\"Already with us,\" Week 3 Gathering). Nothing in it says the fourth child is safe."},{"when":"Day 2, at Ashcombe","line":"*\"Where it forks, the shepherds take the left.\"*","meaning":"True — local knowledge, and the set-up for the \"old ties\" line that follows."},{"when":"Day 5, at the emptied hut","line":"*\"They''re always a step ahead of us.\"*","meaning":"True — they are, and he leads them."},{"when":"","line":"*\"My family''s been in these hills longer than the roads have.\"*","meaning":"True. His family is the old royal house of this land."},{"when":"Day 6, at the cairn","line":"*\"The Kiln. That''s the shepherds'' name for it.\"*","meaning":"True."}]},{"week":4,"entries":[{"when":"Day 1, when someone says the Order could have killed them","line":"*\"Every time they''ve had knives out at you, not one of you has died.\"*","meaning":"True — the Week 1 ambush (his own people) and the three Gatherings. It sounds like luck. On reread it''s the Order''s rule: they need the party alive."},{"when":"Day 1, over Meira''s notes","line":"*\"Reedham''s a fishing village on the Stillwater, two days north. The old village is under the lake. She''s marked the tower that still stands out of the water.\"*","meaning":"True — he reads her shorthand and says only what it says."},{"when":"","line":"*\"It''s the Stones that wake him. Malakor.\"*","meaning":"The single most useful thing he does all season: it makes him indispensable, the trusted authority on what''s really happening."},{"when":"Week 4 Gathering, asked how he knows the king''s name","line":"*\"My grandmother taught me that name.\"*","meaning":"True, and damning on reread."},{"when":"","line":"*\"Four Stones. Four children. That''s the shape of what''s written here.\"*","meaning":"True — *The Verse of the Four*, the page in their hands, says exactly that. The fifth isn''t on that page, and he doesn''t bring it up until the torn page does."},{"when":"","line":"*\"There''s one more. A fifth Stone — she wrote about it.\"*","meaning":"True, and carefully bounded: he reports that she wrote about it, never what she believed it would do. The party supplies \"it can undo this\" themselves — finishing the torn page''s missing ending the way hope demands, not because anyone handed them a false conclusion."},{"when":"If asked why he never mentioned a fifth before.","line":"*\"She wrote it down. I''m telling you now.\"*","meaning":"Both true. He never says he didn''t know, and never says he took it for a poet''s count."},{"when":"If asked why the Order would keep that line.","line":"*\"''Speak true, always.'' It''s their book.\"*","meaning":"True — he points at the page they already hold (the Week 3 doctrine), never at himself. On reread, it''s his own creed."},{"when":"If asked how the Order knew where their maps pointed","line":"*\"Their own book tells you: closer to you than your own shadows.\"*","meaning":"True — it quotes the page in their hands."}]},{"week":5,"entries":[{"when":"","line":"*\"The fifth wasn''t hidden in the hills like the others. Every telling I know ends at Highwall.\"*","meaning":"He doesn''t know the spot (that''s what the party''s blood is for), and he doesn''t say more than he''s asked."},{"when":"Day 1, only if asked how he knows","line":"*\"My family''s been in these hills longer than the roads have.\"*","meaning":"The Ashcombe line, repeated. True."},{"when":"After the failure","line":"*\"The old telling names a place, and a night.\"*","meaning":"True. He''s naming two real missing variables — location and timing — while never naming the one that matters most: whose blood."},{"when":"The cliffhanger, at the moon, seven nights left","line":"*\"We''re early.\"*","meaning":"True. He stands in his ancestor''s city, with the fifth carried there by friends, a full week before the one night his family has waited centuries for. Players hear \"we''re ahead of the night; there is time to find the way in.\" He means early for the waking, not for stopping it, and \"we\" is his house as much as the party. Present tense: no prediction, no promise."}]},{"week":6,"entries":[{"when":"","line":"*\"Let me.\"*","meaning":"The only thing he has needed since Week 1: to stand in that chamber, holding that shard, with the party beside him as friends, not enemies."},{"when":"Asked why his would work when theirs didn''t.","line":"*\"You''ve all tried tonight. I haven''t.\"*","meaning":"True — \"tonight\" keeps it true even if he bled on it at Week 5 when asked."},{"when":"Only after the Stone has answered him","line":"*\"The page said the fifth would end this. It never said whose blood.\"*","meaning":"True of the torn page."},{"when":"A party member: \"You never lied to us. Not once.\"","line":"*\"No. The faithful don''t.\"*","meaning":"True — and the Week 3 doctrine, attached to him out loud at last."},{"when":"Closing the king''s open hand around the fifth","line":"*\"One stayed close. It always did.\"*","meaning":"True. The Seekers'' first fragment said it of the fifth: five fell, four were scattered after, one stayed close. They kept it within sight of his hall for as long as they lived, and tonight it goes back into the hand it was taken from. Heard as an old riddle answered at last; on reread, he says it of his own house too, which kept its watch on that hall for centuries from just up the hill."},{"when":"From the king''s side, after the act","line":"*\"Your Seekers made their children the only key. The key that locks is also the key that unlocks. You were the key.\"*","meaning":"True. The Seekers'' own words, turned onto the party: they made their children the only key, and the key that locks is also the key that unlocks. Only Seeker blood could find the four Stones and wake them; every map the party solved showed the Order where a Stone lay, and the rite that locked the king is the one that wakes him. Heard as a charge against the Seekers; on reread, it is the whole season."},{"when":"","line":"*\"I''ve known what the fifth was since before you found me.\"*","meaning":"True — what it was, and whose. He never knew *where*; that, and the other four, is what he needed the party for."},{"when":"","line":"*\"You saved every child you were sent to save.\"*","meaning":"True. Every one. That was never the part that mattered."},{"when":"Day 1, when someone wonders where the king''s household could have run to","line":"*\"Somewhere they''d never be found.\"*","meaning":"True — they never were found — and on reread, the Order''s whole history in four words: they hid, for centuries, and he is what''s left of them."},{"when":"Day 4, when someone asks how the Order got four Stones into a hall only Seeker blood opens","line":"*\"The Seekers sealed the doors they knew about.\"*","meaning":"True — they never knew the household''s escape stair, which is how the faithful come in at the Gathering. On reread, he''s the one who knows the door they missed."},{"when":"Day 5, under the nearly full moon, after \"The dark moon comes back…\"","line":"*\"It always comes back.\"*","meaning":"True — the moon does. Innocent as an echo of the fragment; on reread, a man who has been waiting his whole life for this one night."}]}]'::jsonb)
on conflict (series_id, season_number) do update set data = excluded.data;
